import ReplayIcon from "@mui/icons-material/Replay";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import { useLocation } from "react-router-dom";
import { FETCH_ALBUM_DOWNLOAD_THUNK } from "../../actions/detailAction";
import AdComponent from "../../components/Ads/AdComponent";
import { CaptchaAlert } from "../../components/Alert/Alert";
import HeaderAds from "../../components/Common/HeaderAds";
import Loading from "../../components/Common/Loading";
import { GoBack } from "../../Hooks";
import { useAppDispatch, useAppSelector } from "../../store/hooks";
import { generateMathProblem } from "../../utils/Function";

const Download = () => {
  const { t } = useTranslation();
  const dispatch = useAppDispatch();
  const location = useLocation();
  const searchParams = new URLSearchParams(location.search);
  const queryId = searchParams.get("id") as string;
  const downloadRules = t("detail.download_rules", { returnObjects: true });
  const { albumDownloadDetail, isDownloadLoading } = useAppSelector((state) => state.detail);
  const [problem, setProblem] = useState(generateMathProblem());
  const [isImgLoaded, setIsImgLoaded] = useState(false);
  const [userAnswer, setUserAnswer] = useState("");
  const [isCorrect, setIsCorrect] = useState<boolean | null>(null);
  const [isLogined, setIsLogined] = useState(true);

  useEffect(() => {
    if (albumDownloadDetail?.status === "0") {
      setIsLogined(false);
    } else {
      setIsLogined(true);
    }
  }, [albumDownloadDetail?.status]);

  useEffect(() => {
    if (queryId) dispatch(FETCH_ALBUM_DOWNLOAD_THUNK(queryId));
  }, [queryId]);

  // 換章節時 img_url 會變，不重置會沿用上一張的載入狀態、新圖直接以 opacity 1 跳出來
  useEffect(() => {
    setIsImgLoaded(false);
  }, [albumDownloadDetail.img_url]);

  const checkAnswer = () => {
    if (userAnswer === problem.answer) {
      setIsCorrect(true);
      const link = document.createElement("a");
      link.href = albumDownloadDetail.download_url;
      link.download = albumDownloadDetail.title;
      link.click();
    } else {
      setIsCorrect(false);
    }
  };

  const regenerateProblem = () => {
    const newProblem = generateMathProblem();
    setProblem(newProblem);
    setUserAnswer("");
    setIsCorrect(null);
  };

  return (
    <div className="min-h-screen dark:bg-bk pb-10">
      {isDownloadLoading ? (
        <Loading />
      ) : (
        <>
          <div className="sticky top-safe z-50">
            <HeaderAds />
            <div className="bg-nbk w-full h-14 text-white flex items-center px-3 py-2">
              <GoBack back={-1} />
              <div className="ml-4">{t("detail.download_page")}</div>
            </div>
          </div>
          <div className="w-full mx-auto flex justify-center my-4">
            {!isDownloadLoading && <AdComponent adKey="download1" />}
          </div>
          <div className="bg-white text-bbk dark:bg-bbk dark:text-tgy m-3 p-4">
            <div className="flex justify-between py-4 word-break">
              <p>{albumDownloadDetail.title}</p>
              <p>{albumDownloadDetail.fileSize}</p>
            </div>
            <div className="relative min-h-80 w-full overflow-hidden rounded-md bg-[#f0f0f0]">
              {!isImgLoaded && <div className="absolute inset-0 animate-pulse bg-[#f0f0f0]" />}
              <img
                src={albumDownloadDetail.img_url || "/images/chapter_default.jpg"}
                alt={albumDownloadDetail.title}
                onLoad={() => setIsImgLoaded(true)}
                onError={(e) => {
                  const target = e.target as HTMLImageElement;
                  // 避免 onError 會無限迴圈
                  if (!target.src.endsWith("/images/chapter_default.jpg")) {
                    target.src = "/images/chapter_default.jpg";
                    return;
                  }
                  setIsImgLoaded(true);
                }}
                className="h-full w-full object-contain"
                style={{ opacity: isImgLoaded ? 1 : 0, transition: "opacity 0.3s ease-in-out" }}
              />
            </div>
            <div className="flex flex-wrap justify-center items-center gap-2 p-6 border border-white rounded-md">
              <p className="text-2xl shrink-0 whitespace-nowrap">{problem.problem} =</p>
              <input
                type="text"
                value={userAnswer}
                maxLength={10}
                onChange={(e) => setUserAnswer(e.target.value)}
                placeholder={t("detail.enter_answer")}
                className="w-32 h-12 shrink-0 px-2"
              />
              <button className="bg-og rounded-md text-white p-3 shrink-0" onClick={checkAnswer}>
                {t("detail.download")}
              </button>
              <ReplayIcon className="text-3xl shrink-0" onClick={regenerateProblem} />
            </div>

            <div className="grid grid-cols-2 gap-2 mb-10">
              <div className="max-h-[120px] overflow-hidden object-top">
                {!isDownloadLoading && <AdComponent adKey="download2" />}
              </div>
              <div className="max-h-[120px] overflow-hidden object-top">
                {!isDownloadLoading && <AdComponent adKey="download3" />}
              </div>
            </div>
            <div className="text-[red] pt-6 pb-72">
              {Array.isArray(downloadRules) && downloadRules.map((d: any) => <p key={d}>{d}</p>)}
            </div>
          </div>
          {(!isLogined || (!isCorrect && isCorrect !== null)) && (
            <CaptchaAlert
              albumDownloadDetail={albumDownloadDetail}
              isLogined={isLogined}
              setIsLogined={setIsLogined}
              isCorrect={isCorrect}
              setIsCorrect={setIsCorrect}
              setUserAnswer={setUserAnswer}
            />
          )}
        </>
      )}
    </div>
  );
};

export default Download;
